"Nigerian bank transfers": "<div class=\"PaymentMethodCard PaymentMethodHubGrid__card\" style=\"--paymentMethodCardaccentColor: #000000\" data-js-controller=\"PaymentMethodHubCard\" data-id=\"Nigerian bank transfers\"><div class=\"PaymentMethodCard__container\"><div class=\"PaymentMethodCard__header\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"150\" height=\"30\" fill=\"none\" viewBox=\"0 0 150 30\" class=\"PaymentMethodLogo\"><path fill=\"var(--paymentMethodLogoColor, #24B47E)\" d=\"M81.29 1v28h8.809c.934 0 1.83-.393 2.491-1.093s1.032-1.65 1.032-2.64V4.733c0-.99-.37-1.94-1.032-2.64A3.426 3.426 0 0090.1 1h-8.81z\"></path><path fill=\"var(--paymentMethodLogoColor, #F6F9FC)\" d=\"M81.29 1H68.955v28h12.333V1z\"></path><path fill=\"var(--paymentMethodLogoColor, #EAEEF3)\" d=\"M68.956 27.133V29h12.333v-1.867H68.956zM68.956 1v1.867h12.333V1H68.956z\"></path><path fill=\"var(--paymentMethodLogoColor, #24B47E)\" d=\"M60.146 1c-.934 0-1.83.393-2.491 1.093a3.85 3.85 0 00-1.032 2.64v20.534c0 .99.37 1.94 1.032 2.64.66.7 1.557 1.093 2.491 1.093h8.81V1h-8.81z\"></path><title>NigerianCards</title></svg></div><div class=\"PaymentMethodCard__body\"><section class=\"Copy variant--Detail\" style=\"--paddingLeft: var(--columnPaddingNone); --paddingRight: var(--columnPaddingNone); --titleAnchorDisplay: none\"><header class=\"Copy__header\"><h1 class=\"Copy__title\"> Nigerian bank transfers <span class=\"PaymentMethodCard__bodyInviteOnlyIndicator\">(Preview)</span></h1></header><div class=\"Copy__body\"> Localize your customer experience and accept payments from the most popular payment methods available in Nigeria without a local Nigerian entity. </div></section><a class=\"CtaButton variant-- CtaButton--arrow PaymentMethodCard__link\" href=\"https://stripe.com/payment-method/nigeria\" data-js-controller=\"AnalyticsButton\" data-js-target=\"PaymentMethodHubCard.link\" data-analytics-category=\"Buttons\" data-analytics-action=\"Clicked\" data-analytics-label=\"nigerian_bank_transfers__learn_more\">Learn more<span class=\"nobr\"><svg class=\"HoverArrow\" width=\"10\" height=\"10\" viewBox=\"0 0 10 10\" aria-hidden=\"true\"><g fill-rule=\"evenodd\"><path class=\"HoverArrow__linePath\" d=\"M0 5h7\"></path><path class=\"HoverArrow__tipPath\" d=\"M1 1l4 4-4 4\"></path></g></svg></span></a></div><div class=\"PaymentMethodCard__footer\"><span class=\"Badge Badge--tooltip\"> Bank transfer <button class=\"PortalTooltipItem TooltipButton TooltipButton--iconSizeNormal\" data-js-controller=\"PortalTooltipItem\"><svg aria-hidden=\"true\" class=\"TooltipButton__icon\" width=\"20\" height=\"20\" viewBox=\"0 0 20 20\" xmlns=\"http://www.w3.org/2000/svg\"><g fill-rule=\"evenodd\"><circle fill=\"var(--tooltipIconBackgroundColor)\" opacity=\"var(--tooltipBackgroundOpacity, .15)\" cx=\"10\" cy=\"10\" r=\"10\"></circle><path fill=\"var(--tooltipIconColor)\" d=\"M10 13.13a1.25 1.25 0 1 1 0 2.5 1.25 1.25 0 0 1 0-2.5zm0-9.07c2 0 3.44 1.31 3.44 3.44 0 1.26-.72 2.25-2 2.92a.93.93 0 0 0-.5.7v.13a.94.94 0 1 1-1.88 0c0-1.05.59-2 1.52-2.5.7-.36.98-.75.98-1.25 0-1.05-.56-1.56-1.56-1.56-.8 0-1.47.61-1.55 1.4l-.01.16a.94.94 0 0 1-1.88 0c0-1.9 1.54-3.44 3.44-3.44z\"></path></g></svg> <span class=\"PortalTooltipItem__tooltip\" data-js-target=\"PortalTooltipItem.tooltip\"> For large transactions, Stripe makes it possible to accept credit transfers or wires with automated reconciliation, lowering the chance of payment failure without adding operational complexity. </span></button></span></div></div><div class=\"PaymentMethodCard__background\"></div></div>",
"Payment on invoice": "<div class=\"PaymentMethodCard PaymentMethodHubGrid__card\" style=\"--paymentMethodCardaccentColor: #000000\" data-js-controller=\"PaymentMethodHubCard\" data-id=\"Payment on invoice\"><div class=\"PaymentMethodCard__container\"><div class=\"PaymentMethodCard__header\"><svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 150 30\" width=\"150\" height=\"30\" class=\"PaymentMethodLogo\"><path fill=\"var(--paymentMethodLogoColor, #4F5B76)\" d=\"M73.75 11.25V5H70a2.5 2.5 0 0 0-2.5 2.5v15A2.5 2.5 0 0 0 70 25h10a2.5 2.5 0 0 0 2.5-2.5v-8.75h-6.25a2.5 2.5 0 0 1-2.5-2.5\"></path><path fill=\"var(--paymentMethodLogoColor, #4F5B76)\" d=\"M82.5 11.25 76.25 5v6.25z\"></path><title>PaymentOnInvoice</title></svg></div><div class=\"PaymentMethodCard__body\"><section class=\"Copy variant--Detail\" style=\"--paddingLeft: var(--columnPaddingNone); --paddingRight: var(--columnPaddingNone); --titleAnchorDisplay: none\"><header class=\"Copy__header\"><h1 class=\"Copy__title\"> Payment on invoice <span class=\"PaymentMethodCard__bodyInviteOnlyIndicator\">(Preview)</span></h1></header><div class=\"Copy__body\"> Allow your customers to pay by invoice, a popular local payment method in Germany giving them the flexibility to pay over time while you get paid up front. </div></section><a class=\"CtaButton variant-- CtaButton--arrow PaymentMethodCard__link\" href=\"https://stripe.com/payment-method/payment-on-invoice\" data-js-controller=\"AnalyticsButton\" data-js-target=\"PaymentMethodHubCard.link\" data-analytics-category=\"Buttons\" data-analytics-action=\"Clicked\" data-analytics-label=\"payment_on_invoice__learn_more\">Learn more<span class=\"nobr\"><svg class=\"HoverArrow\" width=\"10\" height=\"10\" viewBox=\"0 0 10 10\" aria-hidden=\"true\"><g fill-rule=\"evenodd\"><path class=\"HoverArrow__linePath\" d=\"M0 5h7\"></path><path class=\"HoverArrow__tipPath\" d=\"M1 1l4 4-4 4\"></path></g></svg></span></a></div><div class=\"PaymentMethodCard__footer\"><span class=\"Badge Badge--tooltip\"> Buy now, pay later <button class=\"PortalTooltipItem TooltipButton TooltipButton--iconSizeNormal\" data-js-controller=\"PortalTooltipItem\"><svg aria-hidden=\"true\" class=\"TooltipButton__icon\" width=\"20\" height=\"20\" viewBox=\"0 0 20 20\" xmlns=\"http://www.w3.org/2000/svg\"><g fill-rule=\"evenodd\"><circle fill=\"var(--tooltipIconBackgroundColor)\" opacity=\"var(--tooltipBackgroundOpacity, .15)\" cx=\"10\" cy=\"10\" r=\"10\"></circle><path fill=\"var(--tooltipIconColor)\" d=\"M10 13.13a1.25 1.25 0 1 1 0 2.5 1.25 1.25 0 0 1 0-2.5zm0-9.07c2 0 3.44 1.31 3.44 3.44 0 1.26-.72 2.25-2 2.92a.93.93 0 0 0-.5.7v.13a.94.94 0 1 1-1.88 0c0-1.05.59-2 1.52-2.5.7-.36.98-.75.98-1.25 0-1.05-.56-1.56-1.56-1.56-.8 0-1.47.61-1.55 1.4l-.01.16a.94.94 0 0 1-1.88 0c0-1.9 1.54-3.44 3.44-3.44z\"></path></g></svg> <span class=\"PortalTooltipItem__tooltip\" data-js-target=\"PortalTooltipItem.tooltip\"> Offer flexible buy now, pay later payment options that increase your customers’ purchasing power, leading to higher conversion and order value. </span></button></span></div></div><div class=\"PaymentMethodCard__background\"></div></div>",
